function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillBleed(0.2);
  brush.fillTexture(0.5, 0.4);

  // sky
  brush.fill("#8cc0e3", 170);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 230);
  brush.vertex(0, 230);
  brush.endShape(true);

  // distant hills
  brush.fill("#7a9e6a", 160);
  brush.beginShape(0.6);
  brush.vertex(0, 230);
  brush.vertex(100, 190);
  brush.vertex(220, 215);
  brush.vertex(330, 185);
  brush.vertex(400, 210);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // field
  brush.fill("#5f8f3e", 200);
  brush.beginShape(0.2);
  brush.vertex(0, 230);
  brush.vertex(400, 225);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // distant yellow haze of flowers
  brush.fill("#f2c84b", 150);
  for (let i = 0; i < 40; i++) {
    let x = 5 + i * 10;
    let y = 238 + (i % 3) * 5;
    brush.circle(x, y, 5);
  }

  // sunflowers, back rows smaller
  let rows = [
    { y: 270, s: 10, n: 9 },
    { y: 310, s: 15, n: 6 },
    { y: 360, s: 22, n: 4 }
  ];
  for (let r of rows) {
    for (let i = 0; i < r.n; i++) {
      let x = (400 / r.n) * (i + 0.5) + ((i % 2) * 2 - 1) * r.s * 0.3;
      let y = r.y + (i % 2) * r.s * 0.4;
      // stem
      brush.fill("#3f6b2a", 220);
      brush.beginShape(0);
      brush.vertex(x - r.s * 0.12, y);
      brush.vertex(x + r.s * 0.12, y);
      brush.vertex(x + r.s * 0.12, 400);
      brush.vertex(x - r.s * 0.12, 400);
      brush.endShape(true);
      // leaf
      brush.fill("#4f8a34", 200);
      brush.beginShape(0.8);
      brush.vertex(x, y + r.s * 1.8);
      brush.vertex(x + r.s * 1.3, y + r.s * 1.3);
      brush.vertex(x + r.s * 0.6, y + r.s * 2.2);
      brush.endShape(true);
      // petals
      brush.fill("#f5c518", 230);
      for (let k = 0; k < 10; k++) {
        let a = (TWO_PI / 10) * k;
        brush.circle(x + cos(a) * r.s * 0.85, y + sin(a) * r.s * 0.85, r.s * 0.45);
      }
      // centre
      brush.fill("#6b3e1e", 240);
      brush.circle(x, y, r.s * 0.55);
    }
  }
}

