function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  brush.noStroke();
  brush.fillTexture(0.5, 0.4);
  brush.fillBleed(0.2);

  // sky
  brush.fill("#8fc1e3", 170);
  brush.beginShape(0.3);
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(400, 230);
  brush.vertex(0, 230);
  brush.endShape(true);

  // sun glow
  brush.fill("#f7d88a", 160);
  brush.circle(320, 70, 35);

  // distant hills
  brush.fill("#7fa37a", 170);
  brush.beginShape(0.6);
  brush.vertex(0, 230);
  brush.vertex(80, 195);
  brush.vertex(180, 215);
  brush.vertex(290, 190);
  brush.vertex(400, 215);
  brush.vertex(400, 250);
  brush.vertex(0, 250);
  brush.endShape(true);

  // field
  brush.fill("#5d8f3e", 190);
  brush.beginShape(0.2);
  brush.vertex(0, 235);
  brush.vertex(400, 235);
  brush.vertex(400, 400);
  brush.vertex(0, 400);
  brush.endShape(true);

  // distant sunflower dots
  brush.fillBleed(0.1);
  for (let i = 0; i < 26; i++) {
    let x = 8 + i * 15 + (i % 3) * 3;
    let y = 245 + (i % 4) * 5;
    brush.fill("#f2c12e", 210);
    brush.circle(x, y, 5);
  }

  // sunflowers, back to front
  let rows = [
    { y: 280, s: 9, n: 9 },
    { y: 320, s: 14, n: 6 },
    { y: 365, s: 21, n: 4 }
  ];
  for (let r = 0; r < rows.length; r++) {
    let row = rows[r];
    let step = 400 / row.n;
    for (let i = 0; i < row.n; i++) {
      let x = step * (i + 0.5) + ((i * 37 + r * 11) % 17) - 8;
      let y = row.y + ((i * 13) % 9) - 4;
      let s = row.s;
      // stem
      brush.fill("#3e6b2a", 220);
      brush.beginShape(0.2);
      brush.vertex(x - s * 0.12, y);
      brush.vertex(x + s * 0.12, y);
      brush.vertex(x + s * 0.15, min(400, y + s * 4));
      brush.vertex(x - s * 0.15, min(400, y + s * 4));
      brush.endShape(true);
      // leaf
      brush.fill("#4f8a34", 200);
      brush.beginShape(0.7);
      brush.vertex(x, y + s * 1.8);
      brush.vertex(x + s * 1.1, y + s * 1.4);
      brush.vertex(x + s * 0.4, y + s * 2.2);
      brush.endShape(true);
      // petals
      brush.fill("#f5c518", 220);
      for (let p = 0; p < 12; p++) {
        let a = (TWO_PI * p) / 12;
        let px = x + cos(a) * s * 0.9;
        let py = y + sin(a) * s * 0.9;
        brush.circle(constrain(px, 0, 400), constrain(py, 0, 400), s * 0.45);
      }
      brush.fill("#f9dc5c", 150);
      brush.circle(x, y, s * 0.9);
      // centre
      brush.fill("#6b3e1f", 235);
      brush.circle(x, y, s * 0.5);
      brush.fill("#3b2412", 200);
      brush.circle(x + s * 0.1, y + s * 0.1, s * 0.25);
    }
  }
}

